/// Returns the n-th Fibonacci number (0-indexed: fib(0)=0, fib(1)=1).
/// Computes iteratively using constant space.
fn fibonacci(n: u64) -> u64 {
    if n == 0 {
        return 0;
    }
    if n == 1 {
        return 1;
    }

    let mut prev2: u64 = 0; // F(0)
    let mut prev1: u64 = 1; // F(1)
    let mut current: u64 = 0;

    for _ in 2..=n {
        current = prev1 + prev2;
        prev2 = prev1;
        prev1 = current;
    }

    current
}
